import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;

/**
 * Computes a Minimum Spanning Tree (MST) of an undirected, weighted graph using
 * Prim's algorithm.
 *
 * <p>The graph is supplied as a symmetric adjacency matrix where {@code graph[u][v]}
 * is the weight of the edge between vertices {@code u} and {@code v}, and a weight of
 * {@code 0} means there is no edge.
 *
 * <p>This implementation uses a binary heap (priority queue) to select the next
 * cheapest crossing edge, giving a running time of {@code O(E log V)} rather than the
 * {@code O(V^2)} of the naive linear-scan variant.
 */
final class PrimsMst {

    /** Sentinel weight indicating "no edge" in the adjacency matrix. */
    private static final int NO_EDGE = 0;

    private PrimsMst() {
        // Utility class: no instances.
    }

    /**
     * An edge of the minimum spanning tree, connecting {@code from} to {@code to}
     * with the given {@code weight}.
     */
    record Edge(int from, int to, int weight) {}

    /**
     * The result of an MST computation: the chosen edges and their total weight.
     */
    record MstResult(List<Edge> edges, long totalWeight) {
        MstResult {
            edges = List.copyOf(edges);
        }
    }

    /**
     * Computes the minimum spanning tree of the graph described by {@code graph}.
     *
     * @param graph a square, symmetric adjacency matrix; {@code graph[u][v] == 0}
     *              denotes the absence of an edge
     * @return the MST edges (in the order vertices are added) and their total weight
     * @throws IllegalArgumentException if the matrix is null, not square, or the graph
     *                                  is not connected
     */
    static MstResult compute(int[][] graph) {
        int vertexCount = validate(graph);
        if (vertexCount == 0) {
            return new MstResult(List.of(), 0L);
        }

        boolean[] inTree = new boolean[vertexCount];
        List<Edge> mstEdges = new ArrayList<>(vertexCount - 1);
        long totalWeight = 0L;

        // Min-heap of candidate crossing edges, ordered by weight.
        PriorityQueue<Edge> frontier = new PriorityQueue<>((a, b) -> Integer.compare(a.weight(), b.weight()));
        addCrossingEdges(graph, inTree, 0, frontier);

        while (!frontier.isEmpty() && mstEdges.size() < vertexCount - 1) {
            Edge cheapest = frontier.poll();
            if (inTree[cheapest.to()]) {
                continue; // Stale entry: the endpoint was already connected.
            }
            mstEdges.add(cheapest);
            totalWeight += cheapest.weight();
            addCrossingEdges(graph, inTree, cheapest.to(), frontier);
        }

        if (mstEdges.size() != vertexCount - 1) {
            throw new IllegalArgumentException("Graph is not connected; no spanning tree exists.");
        }
        return new MstResult(mstEdges, totalWeight);
    }

    /**
     * Marks {@code vertex} as part of the tree and pushes every edge leading from it to
     * a vertex not yet in the tree onto the frontier.
     */
    private static void addCrossingEdges(int[][] graph, boolean[] inTree, int vertex, PriorityQueue<Edge> frontier) {
        inTree[vertex] = true;
        for (int neighbor = 0; neighbor < graph.length; neighbor++) {
            int weight = graph[vertex][neighbor];
            if (weight != NO_EDGE && !inTree[neighbor]) {
                frontier.add(new Edge(vertex, neighbor, weight));
            }
        }
    }

    /** Validates the adjacency matrix and returns the vertex count. */
    private static int validate(int[][] graph) {
        if (graph == null) {
            throw new IllegalArgumentException("Graph must not be null.");
        }
        for (int[] row : graph) {
            if (row == null || row.length != graph.length) {
                throw new IllegalArgumentException("Adjacency matrix must be square.");
            }
        }
        return graph.length;
    }

    /** Renders an MST result as a human-readable edge/weight table. */
    static String format(MstResult result) {
        StringBuilder sb = new StringBuilder("Edge \tWeight");
        for (Edge edge : result.edges()) {
            sb.append('\n').append(edge.from()).append(" - ").append(edge.to())
              .append('\t').append(edge.weight());
        }
        sb.append("\nTotal weight: ").append(result.totalWeight());
        return sb.toString();
    }

    public static void main(String[] args) {
        int[][] graph = {
            { 0, 2, 0, 6, 0 },
            { 2, 0, 3, 8, 5 },
            { 0, 3, 0, 0, 7 },
            { 6, 8, 0, 0, 9 },
            { 0, 5, 7, 9, 0 },
        };

        System.out.println(format(compute(graph)));
    }
}

